function initialLanguage() {
  const stored = localStorage.getItem("smarttable.lang");
  if (stored) return normalizeLanguage(stored);
  const browserLang = normalizeLanguage(navigator.language || navigator.languages?.[0] || "en");
  return browserLang === "hu" ? "hu" : browserLang === "es" ? "es" : "en";
}

function currentTheme() {
  return document.documentElement.dataset.theme === "dark" ? "dark" : "light";
}

function applyTheme(theme, { persist = true } = {}) {
  const next = theme === "dark" ? "dark" : "light";
  document.documentElement.dataset.theme = next;
  if (persist) localStorage.setItem("smarttable.theme", next);
  const button = document.querySelector("#themeToggleButton");
  const dark = next === "dark";
  const label = dark ? "Use light mode" : "Use dark mode";
  if (button) {
    button.setAttribute("aria-label", label);
    button.setAttribute("title", label);
    button.querySelector("span").textContent = dark ? "☀" : "☾";
  }
  document.querySelector('meta[name="theme-color"]')?.setAttribute("content", dark ? "#101713" : "#0f735d");
}

function readStoredJson(storage, key) {
  try {
    return JSON.parse(storage.getItem(key) || "null");
  } catch {
    storage.removeItem(key);
    return null;
  }
}

function clearStoredSession() {
  localStorage.removeItem("smarttable.session");
  sessionStorage.removeItem("smarttable.session");
}

const AUTH_BROWSER_STATE_RESET_VERSION = "2026-07-31-auth-routing-5";

function isAuthStateResetRoute(pathname = window.location.pathname) {
  const path = String(pathname || "").replace(/\/+$/, "") || "/";
  if (path === "/login") return !state.session;
  return ["/partner", "/admin", "/superadmin"].includes(path) && !state.session;
}

function clearOriginCookies() {
  const host = window.location.hostname;
  for (const rawCookie of document.cookie.split(";")) {
    const name = rawCookie.split("=")[0]?.trim();
    if (!name) continue;
    const expired = `${encodeURIComponent(name)}=; expires=Thu, 01 Jan 1970 00:00:00 GMT; max-age=0; path=/; SameSite=Lax; Secure`;
    document.cookie = expired;
    if (host) document.cookie = `${expired}; domain=${host}`;
    if (host.startsWith("www.")) document.cookie = `${expired}; domain=.${host.slice(4)}`;
  }
}

async function clearAuthBrowserStateForEntryRoute() {
  if (!isAuthStateResetRoute()) return;
  const savedTheme = localStorage.getItem("smarttable.theme");
  state.session = null;
  clearOriginCookies();
  try {
    localStorage.clear();
    if (savedTheme) localStorage.setItem("smarttable.theme", savedTheme);
  } catch {
    clearStoredSession();
  }
  try {
    sessionStorage.clear();
  } catch {
    // Ignore private-mode storage failures.
  }
  try {
    if ("indexedDB" in window && typeof indexedDB.databases === "function") {
      const databases = await indexedDB.databases();
      await Promise.all((databases || [])
        .map((database) => database?.name)
        .filter(Boolean)
        .map((name) => new Promise((resolve) => {
          const request = indexedDB.deleteDatabase(name);
          request.onsuccess = request.onerror = request.onblocked = () => resolve();
        })));
    }
  } catch {
    // IndexedDB cleanup is best-effort.
  }
  try {
    if ("caches" in window) {
      const keys = await caches.keys();
      await Promise.all(keys.map((key) => caches.delete(key)));
    }
  } catch {
    // Cache Storage cleanup is best-effort.
  }
  try {
    if ("serviceWorker" in navigator) {
      const registrations = await navigator.serviceWorker.getRegistrations();
      await Promise.all(registrations
        .filter((registration) => {
          try {
            return new URL(registration.scope).origin === window.location.origin;
          } catch {
            return false;
          }
        })
        .map((registration) => registration.unregister()));
    }
  } catch {
    // Service worker cleanup is best-effort.
  }
  window.__smartTableAuthStateResetVersion = AUTH_BROWSER_STATE_RESET_VERSION;
}

function demoTokenExpiry(accessToken = "") {
  if (!String(accessToken).startsWith("demo.")) return null;
  try {
    const encoded = String(accessToken).slice(5).replace(/-/g, "+").replace(/_/g, "/");
    const padded = encoded.padEnd(Math.ceil(encoded.length / 4) * 4, "=");
    const payload = JSON.parse(atob(padded));
    return Number(payload.exp) || null;
  } catch {
    return null;
  }
}

function sessionExpiryMs(session = {}) {
  const raw = session.expires_at || session.expiresAt;
  if (raw) {
    const numeric = Number(raw);
    if (Number.isFinite(numeric)) return numeric > 100000000000 ? numeric : numeric * 1000;
    const parsed = new Date(raw).getTime();
    if (Number.isFinite(parsed)) return parsed;
  }
  return demoTokenExpiry(session.access_token);
}

function isSessionExpired(session) {
  const expiry = sessionExpiryMs(session);
  return Boolean(expiry && expiry <= Date.now());
}

function isPrivilegedWebSession(session = {}) {
  return ["admin", "super_admin", "field_representative"].includes(normalizeRole(session?.profile?.role));
}

function withSessionExpiry(session, remember = true) {
  if (!session) return null;
  const existingExpiry = sessionExpiryMs(session);
  const fallbackMs = remember ? 30 * 24 * 60 * 60 * 1000 : 12 * 60 * 60 * 1000;
  const expiresAt = existingExpiry || (session.expires_in ? Date.now() + Number(session.expires_in) * 1000 : Date.now() + fallbackMs);
  return { ...session, expires_at: expiresAt };
}

function storedSession() {
  const persisted = readStoredJson(localStorage, "smarttable.session");
  if (persisted && isPrivilegedWebSession(persisted)) {
    // Privileged sessions must never survive a browser restart. Remove legacy
    // persistent admin tokens and require an explicit sign-in instead.
    localStorage.removeItem("smarttable.session");
  }
  const candidates = [
    isPrivilegedWebSession(persisted) ? null : persisted,
    readStoredJson(sessionStorage, "smarttable.session")
  ].filter(Boolean);
  const session = candidates.find((candidate) => !isSessionExpired(candidate));
  if (!session && candidates.length) clearStoredSession();
  return session || null;
}

