function escapeHtml(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

function escapeAttr(value) {
  return escapeHtml(value);
}

function cleanString(value) {
  return String(value ?? "").trim();
}

function safeInternalNavigationUrl(value = "") {
  const raw = String(value || "").trim();
  if (!raw) return "";
  if (/^\/(?!\/)/.test(raw)) return raw;
  try {
    const parsed = new URL(raw, window.location.origin);
    if (parsed.origin !== window.location.origin) return "";
    return `${parsed.pathname}${parsed.search}${parsed.hash}`;
  } catch {
    return "";
  }
}

function showToast(message, durationMs = 3200) {
  if (!toast) return;
  const translatedMessage = translateInlineText(message);
  if (toastMessage) toastMessage.textContent = translatedMessage;
  else toast.textContent = translatedMessage;
  // Keep operational feedback readable even when a browser/extension applies
  // automatic dark-mode color rewriting to form and status elements.
  toast.style.setProperty("background", "#111814", "important");
  toast.style.setProperty("background-image", "linear-gradient(#111814, #111814)", "important");
  toast.style.setProperty("background-color", "#111814", "important");
  toast.style.setProperty("color", "#ffffff", "important");
  toast.style.setProperty("-webkit-text-fill-color", "#ffffff", "important");
  toast.style.setProperty("forced-color-adjust", "none");
  if (toastMessage) {
    toastMessage.style.setProperty("color", "#ffffff", "important");
    toastMessage.style.setProperty("-webkit-text-fill-color", "#ffffff", "important");
  }
  toast.classList.add("show");
  if (toastHideTimer !== null) window.clearTimeout(toastHideTimer);
  toastHideTimer = window.setTimeout(() => {
    toast.classList.remove("show");
    toastHideTimer = null;
  }, Math.max(1200, Number(durationMs) || 3200));
}

let inlineValidationCounter = 0;
let inlineFormValidationInstalled = false;

function isInlineValidationControl(control) {
  return Boolean(control?.matches?.("input:not([type='hidden']):not([type='submit']):not([type='button']):not([type='reset']), select, textarea"));
}

function relatedValidationControls(control) {
  if (!isInlineValidationControl(control)) return [];
  const form = control.form;
  const type = String(control.type || "").toLowerCase();
  if (!form || !control.name || !["checkbox", "radio"].includes(type)) return [control];
  return Array.from(form.elements).filter((candidate) => isInlineValidationControl(candidate) && candidate.name === control.name);
}

function validationFeedbackKey(control) {
  const controls = relatedValidationControls(control);
  const primary = controls[0] || control;
  if (!primary.dataset.inlineValidationKey) {
    inlineValidationCounter += 1;
    primary.dataset.inlineValidationKey = `field-${inlineValidationCounter}`;
  }
  controls.forEach((candidate) => {
    candidate.dataset.inlineValidationKey = primary.dataset.inlineValidationKey;
  });
  return primary.dataset.inlineValidationKey;
}

function validationFeedbackHost(control) {
  const type = String(control?.type || "").toLowerCase();
  if (["checkbox", "radio"].includes(type)) {
    return control.closest("fieldset, .signup-chip-grid, .signup-consent-list, .checkbox-row, .check-row, .check, label") || control.parentElement;
  }
  return control.closest("label, .guest-field, .form-field, .field, td") || control.parentElement;
}

function inlineValidationMessage(control) {
  const validity = control?.validity;
  if (!validity) return t("form_validation_invalid", "Check this field.");
  if (validity.valueMissing) return t("form_validation_required", "This field is required.");
  if (validity.typeMismatch && control.type === "email") return t("form_validation_email", "Enter a valid email address.");
  if (validity.typeMismatch && control.type === "url") return t("form_validation_url", "Enter a valid web address.");
  if (validity.tooShort) return contentTemplate("form_validation_too_short", "Use at least {{count}} characters.", { count: control.minLength });
  if (validity.tooLong) return contentTemplate("form_validation_too_long", "Use no more than {{count}} characters.", { count: control.maxLength });
  if (validity.rangeUnderflow) return contentTemplate("form_validation_minimum", "Enter a value of at least {{value}}.", { value: control.min });
  if (validity.rangeOverflow) return contentTemplate("form_validation_maximum", "Enter a value no greater than {{value}}.", { value: control.max });
  if (validity.stepMismatch || validity.badInput) return t("form_validation_number", "Enter a valid number.");
  if (validity.patternMismatch) return t("form_validation_format", "Use the requested format.");
  return cleanString(control.validationMessage) || t("form_validation_invalid", "Check this field.");
}

function clearInlineFieldFeedback(control) {
  if (!isInlineValidationControl(control)) return;
  const controls = relatedValidationControls(control);
  const key = controls[0]?.dataset.inlineValidationKey || control.dataset.inlineValidationKey;
  controls.forEach((candidate) => {
    candidate.classList.remove("is-field-invalid", "is-field-warning");
    candidate.removeAttribute("aria-invalid");
    candidate.removeAttribute("data-field-warning");
    if (key) {
      const describedBy = String(candidate.getAttribute("aria-describedby") || "")
        .split(/\s+/)
        .filter((value) => value && value !== `${key}-feedback`)
        .join(" ");
      if (describedBy) candidate.setAttribute("aria-describedby", describedBy);
      else candidate.removeAttribute("aria-describedby");
    }
  });
  if (!key) return;
  document.querySelectorAll(`[data-inline-validation-for="${key}"]`).forEach((feedback) => {
    const host = feedback.parentElement;
    feedback.remove();
    if (host && !host.querySelector(".inline-field-feedback")) {
      host.classList.remove("has-field-error", "has-field-warning");
    }
  });
}

function markInlineFieldFeedback(control, message, { severity = "error" } = {}) {
  if (!isInlineValidationControl(control)) return null;
  clearInlineFieldFeedback(control);
  const controls = relatedValidationControls(control);
  const primary = controls[0] || control;
  const key = validationFeedbackKey(primary);
  const host = validationFeedbackHost(primary);
  if (!host) return null;
  const warning = severity === "warning";
  controls.forEach((candidate) => {
    candidate.classList.add(warning ? "is-field-warning" : "is-field-invalid");
    if (warning) candidate.setAttribute("data-field-warning", "true");
    else candidate.setAttribute("aria-invalid", "true");
    const describedBy = new Set(String(candidate.getAttribute("aria-describedby") || "").split(/\s+/).filter(Boolean));
    describedBy.add(`${key}-feedback`);
    candidate.setAttribute("aria-describedby", [...describedBy].join(" "));
  });
  host.classList.add(warning ? "has-field-warning" : "has-field-error");
  const feedback = document.createElement("small");
  feedback.id = `${key}-feedback`;
  feedback.className = `${warning ? "field-warning" : "field-error"} inline-field-feedback`;
  feedback.dataset.inlineValidationFor = key;
  feedback.setAttribute("role", warning ? "status" : "alert");
  feedback.textContent = message || inlineValidationMessage(primary);
  host.append(feedback);
  return primary;
}

function formControlsNamed(form, name) {
  if (!form || !name) return [];
  return Array.from(form.querySelectorAll("input, select, textarea"))
    .filter((control) => control.name === name || control.dataset.field === name);
}

function markFormFieldFeedback(form, name, message, options = {}) {
  const controls = formControlsNamed(form, name);
  if (!controls.length) return null;
  return markInlineFieldFeedback(controls.find((control) => control.type !== "hidden") || controls[0], message, options);
}

function focusValidationControl(control) {
  if (!control) return;
  window.setTimeout(() => {
    control.scrollIntoView?.({ behavior: "smooth", block: "center" });
    control.focus?.({ preventScroll: true });
  }, 0);
}

function notifyHighlightedFormErrors() {
  showToast(t("form_validation_review_highlighted", "Review the highlighted fields and correct the indicated errors."), 4600);
}

function customFormValidationErrors(form) {
  const errors = [];
  const value = (name) => cleanString(formControlsNamed(form, name).find((control) => control.type !== "hidden")?.value);
  const add = (name, message) => {
    if (formControlsNamed(form, name).length) errors.push({ name, message });
  };
  const password = value("password");
  const confirmation = value("confirm_password");
  if (confirmation || formControlsNamed(form, "confirm_password").length) {
    if (password && passwordStrength(password).score < 5) {
      add("password", t("signup_error_password", "Use at least 8 characters with uppercase, lowercase, number, and symbol."));
    }
    if (password && confirmation && password !== confirmation) {
      add("confirm_password", t("signup_error_password_match", "Passwords must match."));
    }
  }
  const startTime = value("start_time");
  const endTime = value("end_time");
  if (startTime && endTime && endTime <= startTime) {
    add("end_time", t("form_validation_time_order", "End time must be later than start time."));
  }
  const eventStart = value("event_start_time");
  const eventEnd = value("event_end_time");
  if (eventStart && eventEnd && eventEnd <= eventStart) {
    add("event_end_time", t("form_validation_time_order", "End time must be later than start time."));
  }
  const fromDate = value("from");
  const toDate = value("to");
  if (fromDate && toDate && toDate < fromDate) {
    add("to", t("form_validation_date_order", "End date must be on or after start date."));
  }
  for (const name of ["holiday_exceptions", "temporary_closures", "dining_areas", "tables", "capacity_overrides"]) {
    const json = value(name);
    if (!json) continue;
    try {
      JSON.parse(json);
    } catch {
      add(name, t("form_validation_json", "Enter valid JSON data."));
    }
  }
  const latitude = value("latitude");
  if (latitude && (!Number.isFinite(Number(latitude)) || Number(latitude) < -90 || Number(latitude) > 90)) {
    add("latitude", t("form_validation_latitude", "Latitude must be between -90 and 90."));
  }
  const longitude = value("longitude");
  if (longitude && (!Number.isFinite(Number(longitude)) || Number(longitude) < -180 || Number(longitude) > 180)) {
    add("longitude", t("form_validation_longitude", "Longitude must be between -180 and 180."));
  }
  return errors;
}

function installInlineFormValidation() {
  if (inlineFormValidationInstalled) return;
  inlineFormValidationInstalled = true;
  document.addEventListener("invalid", (event) => {
    const control = event.target;
    if (!isInlineValidationControl(control)) return;
    event.preventDefault();
    const form = control.form;
    form?.classList.add("form-validation-attempted");
    const firstInvalid = !form?.querySelector(".is-field-invalid");
    markInlineFieldFeedback(control, inlineValidationMessage(control));
    if (firstInvalid) {
      focusValidationControl(control);
      notifyHighlightedFormErrors();
    }
  }, true);
  document.addEventListener("submit", (event) => {
    const form = event.target;
    if (!(form instanceof HTMLFormElement)) return;
    form.classList.add("form-validation-attempted");
    const invalidControls = Array.from(form.elements)
      .filter((control) => isInlineValidationControl(control) && control.willValidate && !control.validity.valid);
    const customErrors = invalidControls.length ? [] : customFormValidationErrors(form);
    if (!invalidControls.length && !customErrors.length) return;
    event.preventDefault();
    event.stopImmediatePropagation();
    invalidControls.forEach((control) => markInlineFieldFeedback(control, inlineValidationMessage(control)));
    customErrors.forEach(({ name, message }) => markFormFieldFeedback(form, name, message));
    const firstCustomControl = customErrors.length ? formControlsNamed(form, customErrors[0].name)[0] : null;
    focusValidationControl(invalidControls[0] || firstCustomControl);
    notifyHighlightedFormErrors();
  }, true);
  const refreshFeedback = (event) => {
    const control = event.target;
    if (!isInlineValidationControl(control)) return;
    const form = control.form;
    if (form?.classList.contains("form-validation-attempted") && control.willValidate && !control.validity.valid) {
      markInlineFieldFeedback(control, inlineValidationMessage(control));
      return;
    }
    clearInlineFieldFeedback(control);
  };
  document.addEventListener("input", refreshFeedback, true);
  document.addEventListener("change", refreshFeedback, true);
  document.addEventListener("focusout", (event) => {
    const control = event.target;
    if (!isInlineValidationControl(control) || !control.willValidate || control.validity.valid || !cleanString(control.value)) return;
    markInlineFieldFeedback(control, inlineValidationMessage(control));
  }, true);
}

function setButtonPending(button, pending, label = t("saving_button", "Saving...")) {
  if (!button) return;
  if (pending) {
    if (!button.dataset.originalText) button.dataset.originalText = button.textContent;
    button.disabled = true;
    button.setAttribute("aria-busy", "true");
    button.textContent = label;
    return;
  }
  if (button.dataset.originalText) button.textContent = button.dataset.originalText;
  delete button.dataset.originalText;
  button.disabled = false;
  button.removeAttribute("aria-busy");
}

async function api(path, options = {}) {
  return requestJson(path, options, currentSession);
}

function queryStringFromFilters(filters = {}) {
  const params = new URLSearchParams();
  Object.entries(filters).forEach(([key, value]) => {
    const cleaned = String(value || "").trim();
    if (!cleaned || cleaned === "all") return;
    params.set(key, cleaned);
  });
  const query = params.toString();
  return query ? `?${query}` : "";
}

function currentPlatformMode() {
  return normalizePlatformMode(state.config?.platform_mode || state.platformMode || "basic");
}

function isBasicMode() {
  return currentPlatformMode() === platformModes.basic;
}

function isAIConciergeMode() {
  return currentPlatformMode() === platformModes.ai_concierge;
}

function aiDemoVisibilityEnabled() {
  return normalizeBooleanSetting(state.config?.ai_demo_visibility ?? state.aiDemoVisibility, false);
}

function publicAiBadgeEnabled() {
  return normalizeBooleanSetting(state.config?.show_ai_mode_badge ?? state.showAiModeBadge, true);
}

function isAiDemoVisible() {
  return isAIConciergeMode() && aiDemoVisibilityEnabled();
}

function shouldShowAiModeBadge() {
  return isAIConciergeMode() && publicAiBadgeEnabled();
}

function registryEntry(featureKey) {
  return state.featureRegistry?.[featureKey] || defaultFeatureRegistry[featureKey] || null;
}

function isFeatureFlagEnabled(flagKey) {
  if (!flagKey) return true;
  const flags = normalizeFeatureFlagSettings(state.config?.feature_flags || state.featureFlags || {});
  return flags[flagKey] !== false;
}

function normalizeFeatureOptions(options = {}) {
  if (typeof options === "string") return { audience: options };
  return options || {};
}

function canShowFeature(featureKey, options = {}) {
  const opts = normalizeFeatureOptions(options);
  const feature = registryEntry(featureKey);
  if (!feature) return false;
  const mode = opts.mode || currentPlatformMode();
  if (!Array.isArray(feature.modes) || !feature.modes.includes(mode)) return false;
  if (!isFeatureFlagEnabled(feature.flag_key || feature.feature_flag)) return false;
  const status = String(feature.status || "disabled");
  if (status === "disabled" || status === "hidden") return false;
  if (opts.public === true && feature.public_visibility !== true) return false;
  if (opts.audience) {
    const audiences = feature.audiences || ["all"];
    if (!audiences.includes("all") && !audiences.includes(opts.audience)) return false;
  }
  if (opts.permission === "super_admin" && !isSuperAdmin()) return false;
  if (opts.requireWorking === true && status !== "working") return false;
  if (status === "demo") return isAiDemoVisible();
  return status === "working";
}

function featureVisibilityLabel(feature = {}) {
  if (!isFeatureFlagEnabled(feature.flag_key || feature.feature_flag)) return t("feature_flag_disabled_label", "Disabled by feature flag");
  const status = String(feature.status || "disabled");
  if (status === "demo") return isAiDemoVisible() ? t("feature_visible_preview", "Visible as Preview") : t("feature_hidden_demo_off", "Hidden until AI Demo Visibility is On");
  if (status === "working") return t("feature_visible_working", "Visible");
  if (status === "hidden") return t("feature_hidden_label", "Hidden");
  return t("feature_disabled_label", "Disabled");
}

function demoBadge(label = t("platformMode.demo", "Demo")) {
  return `<span class="demo-badge">${escapeHtml(label)}</span>`;
}

function aiModeBanner(audience = "guest") {
  if (!shouldShowAiModeBadge()) return "";
  const preview = isAiDemoVisible();
  return `
    <div class="ai-mode-banner ${preview ? "preview" : "live"}" data-ai-mode-banner="${escapeAttr(audience)}">
      <strong>${escapeHtml(preview ? t("ai_concierge_preview_badge", "AI Concierge Preview") : t("ai_concierge_public_badge", "SmartTable AI Concierge"))}</strong>
      <span>${escapeHtml(preview ? t("ai_preview_banner_body", "Demo AI features are clearly labeled as preview experiences.") : t("ai_public_banner_body", "AI Concierge tools are enabled for this experience."))}</span>
    </div>
  `;
}

function currentAiRoute() {
  const path = window.location.pathname.replace(/\/+$/, "") || "/";
  const hash = window.location.hash;
  const routes = {
    "/ai-concierge": { key: "guest-ai-concierge", mode: "guest", feature: "ai.concierge", audience: "guest", target: "#ai-concierge" },
    "#ai-concierge": { key: "guest-ai-concierge", mode: "guest", feature: "ai.concierge", audience: "guest", target: "#ai-concierge" },
    "/ai-preferences": { key: "guest-ai-preferences", mode: "guest", feature: "ai.preferenceSurvey", audience: "guest", target: "#ai-preferences" },
    "#ai-preferences": { key: "guest-ai-preferences", mode: "guest", feature: "ai.preferenceSurvey", audience: "guest", target: "#ai-preferences" },
    "/partner/ai-demand": { key: "partner-ai-demand", mode: "partner", feature: "ai.partnerDemand", audience: "partner", target: "#partner-ai-demand" },
    "#partner-ai-demand": { key: "partner-ai-demand", mode: "partner", feature: "ai.partnerDemand", audience: "partner", target: "#partner-ai-demand" },
    "/admin/ai-controls": { key: "admin-ai-controls", mode: "admin", feature: "ai.adminAIControls", audience: "admin", target: "#admin-ai-controls" },
    "#admin-ai-controls": { key: "admin-ai-controls", mode: "admin", feature: "ai.adminAIControls", audience: "admin", target: "#admin-ai-controls" }
  };
  return routes[path] || routes[hash] || null;
}

function aiRouteAccess(route = currentAiRoute()) {
  if (!route) return { route: null, allowed: true };
  const feature = registryEntry(route.feature) || {};
  if (!isAIConciergeMode()) {
    return { route, allowed: false, reason: t("ai_route_unavailable_basic", "This AI experience is hidden in Basic reservation marketplace mode.") };
  }
  if (String(feature.status || "") === "demo" && !isAiDemoVisible()) {
    return { route, allowed: false, reason: t("ai_route_unavailable_demo", "This AI route is a demo preview. Turn AI Demo Visibility On in Super Admin settings to open it.") };
  }
  if (!canShowFeature(route.feature, { audience: route.audience })) {
    return { route, allowed: false, reason: t("ai_route_unavailable_feature", "This AI feature is currently unavailable.") };
  }
  return { route, allowed: true };
}

function currentProtectedAreaRoute() {
  const path = window.location.pathname.replace(/\/+$/, "") || "/";
  const hash = window.location.hash;
  const partnerTargets = {
    "/partner": "#partner-tab-panel-overview",
    "/partner/offers": "#partner-tab-panel-offers",
    "/partner/food-feed": "#partner-food-feed",
    "/partner/reservations": "#partner-tab-panel-reservations",
    "/partner/profile": "#partner-tab-panel-profile",
    "/partner/capacity": "#partner-tab-panel-capacity",
    "/partner/availability": "#partner-tab-panel-availability",
    "/partner/notifications": "#partner-tab-panel-notifications",
    "/partner/reviews": "#partner-tab-panel-reviews",
    "/partner/billing": "#partner-tab-panel-billing",
    "/partner/analytics": "#partner-tab-panel-analytics",
    "/partner/settings": "#partner-tab-panel-profile"
  };
  const adminTargets = {
    "/admin": "#admin-tab-panel-overview",
    "/admin/restaurants": "#admin-tab-panel-restaurants",
    "/admin/partners": "#admin-tab-panel-partners",
    "/admin/reservations": "#admin-tab-panel-reservations",
    "/admin/offers": "#admin-tab-panel-offers",
    "/admin/food-feed": "#admin-tab-panel-food-feed",
    "/admin/users": "#admin-tab-panel-partners",
    "/admin/notifications": "#admin-tab-panel-notifications",
    "/admin/payments": "#admin-tab-panel-payments",
    "/admin/reports": "#admin-tab-panel-reports",
    "/admin/reviews": "#admin-tab-panel-reviews",
    "/admin/settings": "#admin-tab-panel-settings",
    "/admin/audit": "#admin-tab-panel-audit",
    "/admin/content": "#admin-tab-panel-settings",
    "/admin/platform-settings": "#admin-tab-panel-settings",
    "/admin/analytics": "#admin-tab-panel-reports",
    "/admin/field-team": "#admin-tab-panel-field-team"
  };
  const superAdminTargets = {
    "/superadmin": "#superadmin-tab-panel-overview",
    "/superadmin/restaurants": "#superadmin-tab-panel-restaurants",
    "/superadmin/partners": "#superadmin-tab-panel-partners",
    "/superadmin/reservations": "#superadmin-tab-panel-reservations",
    "/superadmin/offers": "#superadmin-tab-panel-offers",
    "/superadmin/food-feed": "#superadmin-tab-panel-food-feed",
    "/superadmin/users": "#superadmin-tab-panel-partners",
    "/superadmin/notifications": "#superadmin-tab-panel-notifications",
    "/superadmin/payments": "#superadmin-tab-panel-payments",
    "/superadmin/reports": "#superadmin-tab-panel-reports",
    "/superadmin/reviews": "#superadmin-tab-panel-reviews",
    "/superadmin/settings": "#superadmin-tab-panel-settings",
    "/superadmin/audit": "#superadmin-tab-panel-audit",
    "/superadmin/analytics": "#superadmin-tab-panel-reports",
    "/superadmin/field-team": "#superadmin-tab-panel-field-team"
  };
  if (path === "/account" || path.startsWith("/account/") || hash === "#guest-account") {
    return { area: "guest", mode: "guest", loginRole: "guest" };
  }
  if (path === "/admin" || path.startsWith("/admin/") || /^#admin(?:-|$)/.test(hash)) {
    return { area: "admin", mode: "admin", loginRole: "admin", target: adminTargets[path] || hash || "#admin-stats" };
  }
  if (path === "/superadmin" || path.startsWith("/superadmin/")) {
    return { area: "superadmin", mode: "admin", loginRole: "admin", target: superAdminTargets[path] || "#admin-platform-settings" };
  }
  if (path === "/partner" || path.startsWith("/partner/") || path.startsWith("/restaurant/") || /^#partner(?:-|$)/.test(hash)) {
    return { area: "partner", mode: "partner", loginRole: "partner", target: partnerTargets[path] || hash || "" };
  }
  return null;
}

function hasProtectedAreaAccess(area) {
  const role = normalizeRole(currentSession()?.profile?.role);
  if (area === "guest") return role === "guest";
  if (area === "partner") return role === "partner";
  if (area === "admin") return isAdminRole(role);
  if (area === "superadmin") return role === "super_admin";
  return false;
}

function protectedAreaLabel(area) {
  if (area === "superadmin") return t("protected_area_superadmin", "superadmin dashboard");
  if (area === "admin") return t("protected_area_admin", "admin dashboard");
  if (area === "partner") return t("protected_area_partner", "partner dashboard");
  return t("protected_area_guest", "guest account");
}

function currentFullRoute() {
  return `${window.location.pathname}${window.location.search}${window.location.hash}`;
}

function renderForbiddenRoute(route) {
  app.innerHTML = `
    ${layoutHero(`
      <section class="login-card unavailable-route-card" role="alert">
        <span class="section-kicker">${escapeHtml(t("route_forbidden_kicker", "Access protected"))}</span>
        <h2>${escapeHtml(t("route_forbidden_title", "You do not have access to this area"))}</h2>
        <p class="muted">${escapeHtml(t("route_forbidden_body", "This account cannot open the selected SmartTable area."))}</p>
        <p class="form-note">${escapeHtml(t("route_forbidden_area_note", "Requested area"))}: ${escapeHtml(protectedAreaLabel(route.area))}</p>
        <div class="button-row">
          <button class="primary-button" id="routeHomeFallback" type="button">${escapeHtml(t("route_go_home", "Go to marketplace"))}</button>
          <button class="ghost-button" id="routeCorrectLogin" type="button">${escapeHtml(t("route_sign_in_correct", "Sign in with another account"))}</button>
        </div>
      </section>
    `)}
  `;
  finalizeRenderedLanguage();
  document.querySelector("#routeHomeFallback")?.addEventListener("click", async () => {
    history.pushState(null, "", "/");
    state.mode = "guest";
    await renderCurrentMode();
  });
  document.querySelector("#routeCorrectLogin")?.addEventListener("click", async () => {
    state.postLoginRedirect = currentFullRoute();
    saveSession(null);
    clearGuestPrivateState();
    state.mode = route.mode;
    renderLogin(route.loginRole);
  });
}

function guardProtectedAreaRoute(route) {
  if (!route) return false;
  state.mode = route.mode;
  if (!currentSession()) {
    state.postLoginRedirect = currentFullRoute();
    renderLogin(route.loginRole);
    return true;
  }
  if (!hasProtectedAreaAccess(route.area)) {
    renderForbiddenRoute(route);
    return true;
  }
  return false;
}

function renderUnavailableRoute(access) {
  const route = access?.route || currentAiRoute();
  const title = route?.mode === "partner"
    ? t("ai_route_partner_unavailable_title", "Partner AI Demand is unavailable")
    : route?.mode === "admin"
      ? t("ai_route_admin_unavailable_title", "Admin AI Controls are unavailable")
      : t("ai_route_guest_unavailable_title", "AI Concierge is unavailable");
  app.innerHTML = `
    ${layoutHero(`
      <section class="login-card unavailable-route-card">
        <span class="section-kicker">${escapeHtml(t("ai_concierge_nav_label", "AI Concierge"))}</span>
        <h2>${escapeHtml(title)}</h2>
        <p class="muted">${escapeHtml(access?.reason || t("ai_route_unavailable_feature", "This AI feature is currently unavailable."))}</p>
        <div class="button-row">
          <button class="primary-button" id="guestNavFallback" type="button">${escapeHtml(t("nav_offers", "Offers"))}</button>
          ${isSuperAdmin() ? `<button class="ghost-button" id="adminNavFallback" type="button">${escapeHtml(t("platformMode.title", "Platform Mode"))}</button>` : ""}
        </div>
      </section>
    `)}
  `;
  finalizeRenderedLanguage();
  document.querySelector("#guestNavFallback")?.addEventListener("click", async () => {
    history.pushState(null, "", "/");
    state.mode = "guest";
    await renderCurrentMode();
  });
  document.querySelector("#adminNavFallback")?.addEventListener("click", async () => {
    location.hash = "#admin-platform-settings";
    state.mode = "admin";
    await renderCurrentMode();
  });
}

function applyRouteIntent(route = currentAiRoute()) {
  if (!route) return;
  state.mode = route.mode;
  if (route.key === "guest-ai-preferences") state.aiWizardOpen = true;
}

function scrollToRouteTarget(route = currentAiRoute()) {
  if (!route?.target) return;
  window.setTimeout(() => {
    document.querySelector(route.target)?.scrollIntoView({ behavior: "smooth", block: "start" });
  }, 80);
}

function platformModeLabel(mode = currentPlatformMode()) {
  return mode === "ai_concierge"
    ? t("platformMode.aiConcierge", "AI Concierge version")
    : t("platformMode.basic", "Basic reservation marketplace");
}

async function loadJson(path) {
  const response = await fetch(path, { cache: "no-store" });
  if (!response.ok) return {};
  return response.json().catch(() => ({}));
}

async function loadTranslations() {
  const [fallback, current] = await Promise.all([
    state.fallbackTranslations && Object.keys(state.fallbackTranslations).length ? Promise.resolve(state.fallbackTranslations) : loadJson("/locales/en.json"),
    state.lang === "en" ? Promise.resolve({}) : loadJson(`/locales/${state.lang}.json`)
  ]);
  state.fallbackTranslations = fallback || {};
  state.translations = state.lang === "en" ? state.fallbackTranslations : { ...state.fallbackTranslations, ...(current || {}) };
}

function t(key, fallback = "") {
  for (const value of [state.content[key], state.translations[key], state.fallbackTranslations[key]]) {
    if (value === undefined || value === null) continue;
    if (typeof value === "string" && !value.trim()) continue;
    if (state.lang !== "en" && fallback && value === fallback) continue;
    return value;
  }
  return translateLiteral(fallback);
}

function literalDictionary() {
  return state.translations?._literals || {};
}

function phraseDictionary() {
  return state.translations?._phrases || {};
}

function translateLiteral(value) {
  if (state.lang === "en") return value;
  const text = String(value ?? "");
  if (!text) return value;
  return literalDictionary()[text] || text;
}

function translateInlineText(value) {
  if (state.lang === "en") return value;
  const original = String(value ?? "");
  const trimmed = original.trim();
  if (!trimmed) return original;
  const exact = literalDictionary()[trimmed];
  if (exact) return original.replace(trimmed, exact);
  let translated = trimmed;
  const phrases = phraseDictionary();
  for (const [source, target] of Object.entries(phrases).sort((a, b) => b[0].length - a[0].length)) {
    translated = translated.replaceAll(source, target);
  }
  return original.replace(trimmed, translated);
}

function uiText(value) {
  return state.lang === "en" ? String(value ?? "") : translateInlineText(value);
}

function translateRenderedStaticText(root = app) {
  if (state.lang === "en" || !root) return;
  const skipTags = new Set(["SCRIPT", "STYLE", "TEXTAREA", "INPUT"]);
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
    acceptNode(node) {
      const parent = node.parentElement;
      if (!parent || skipTags.has(parent.tagName) || parent.closest("[data-no-i18n]")) return NodeFilter.FILTER_REJECT;
      return node.nodeValue.trim() ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_REJECT;
    }
  });
  const nodes = [];
  while (walker.nextNode()) nodes.push(walker.currentNode);
  nodes.forEach((node) => {
    node.nodeValue = translateInlineText(node.nodeValue);
  });
  root.querySelectorAll("[placeholder], [aria-label], [title], [alt]").forEach((element) => {
    ["placeholder", "aria-label", "title", "alt"].forEach((attr) => {
      const value = element.getAttribute(attr);
      if (value) element.setAttribute(attr, translateInlineText(value));
    });
  });
}

function bindReviewPhotoFallbacks(root = app) {
  root.querySelectorAll("[data-review-photo-img]").forEach((image) => {
    const markFailed = () => image.closest("article")?.classList.add("image-failed");
    image.addEventListener("error", markFailed, { once: true });
    if (image.complete && image.naturalWidth === 0) markFailed();
  });
}

function finalizeRenderedLanguage() {
  bindReviewPhotoFallbacks(app);
  translateRenderedStaticText(app);
  updateChromeText();
}

function normalizeRole(role) {
  const value = String(role || "guest").trim().toLowerCase();
  if (["owner", "restaurant_owner", "restaurant", "restaurant_partner"].includes(value)) return "partner";
  if (["superadmin", "super-admin"].includes(value)) return "super_admin";
  if (["field-representative", "field_rep", "representative", "territory_admin"].includes(value)) return "field_representative";
  return value;
}

function isAdminRole(role) {
  const normalized = normalizeRole(role);
  return normalized === "admin" || normalized === "super_admin" || normalized === "field_representative";
}

function isFieldRepresentativeSession() {
  return normalizeRole(currentSession()?.profile?.role) === "field_representative";
}

function currentFieldRepresentativeAccess() {
  return state.adminAccessContext?.access || {};
}

function assignedFieldRepresentativeMarkets() {
  return Array.isArray(state.adminAccessContext?.markets) ? state.adminAccessContext.markets : [];
}

function fieldRepresentativeMarketLabel(market = {}) {
  return market.label || market.name || [market.city, market.region, market.country].filter(Boolean).join(", ") || market.id || "Market";
}

function appModeForRole(role) {
  const normalized = normalizeRole(role);
  if (isAdminRole(normalized)) return "admin";
  if (normalized === "partner") return "partner";
  return "guest";
}

function defaultDashboardRouteForRole(role) {
  const normalized = normalizeRole(role);
  if (normalized === "super_admin") return "/superadmin";
  if (normalized === "admin" || normalized === "field_representative") return "/admin";
  if (normalized === "partner") return "/partner";
  return "/account";
}

function adminDashboardRouteForRole(role) {
  const normalized = normalizeRole(role);
  if (normalized === "super_admin") return safeStoredDashboardRoute("superadmin", "/superadmin");
  return safeStoredDashboardRoute("admin", "/admin");
}

function updateAdminDashboardNav(session = currentSession()) {
  if (!adminDashboardNav) return;
  const role = normalizeRole(session?.profile?.role || "");
  const visible = role === "admin" || role === "super_admin" || role === "field_representative";
  adminDashboardNav.hidden = !visible;
  adminDashboardNav.toggleAttribute("data-authenticated-admin-nav", visible);
  if (!visible) {
    adminDashboardNav.removeAttribute("data-dashboard-route");
    adminDashboardNav.removeAttribute("aria-label");
    adminDashboardNav.textContent = t("admin_dashboard_return_button", "Back to Admin Dashboard");
    return;
  }
  const superAdmin = role === "super_admin";
  const fullLabel = superAdmin
    ? t("superadmin_dashboard_return_button", "Back to Super Admin Dashboard")
    : t("admin_dashboard_return_button", "Back to Admin Dashboard");
  const compactLabel = t("admin_dashboard_return_button_compact", "Admin");
  adminDashboardNav.dataset.dashboardRoute = adminDashboardRouteForRole(role);
  adminDashboardNav.setAttribute("aria-label", fullLabel);
  adminDashboardNav.innerHTML = `
    <span class="admin-dashboard-nav__full">${escapeHtml(fullLabel)}</span>
    <span class="admin-dashboard-nav__compact" aria-hidden="true">${escapeHtml(compactLabel)}</span>
  `;
}

function updateAuthDiagnostics(update = {}) {
  state.authDiagnostics = {
    ...state.authDiagnostics,
    ...update
  };
}

function canRenderLoginDiagnostics() {
  const health = state.runtimeHealth || {};
  return health.production_runtime !== true
    && health.runtime_mode !== "production"
    && health.environment !== "production"
    && health.login_diagnostics_enabled === true;
}

function protectedAreaForPath(pathname = "") {
  const path = String(pathname || "").replace(/\/+$/, "") || "/";
  if (path === "/account" || path.startsWith("/account/")) return "guest";
  if (path === "/partner" || path.startsWith("/partner/") || path.startsWith("/restaurant/")) return "partner";
  if (path === "/superadmin" || path.startsWith("/superadmin/")) return "superadmin";
  if (path === "/admin" || path.startsWith("/admin/")) return "admin";
  return "";
}

function roleCanAccessArea(role, area) {
  const normalized = normalizeRole(role);
  if (area === "guest") return normalized === "guest";
  if (area === "partner") return normalized === "partner";
  if (area === "admin") return isAdminRole(normalized);
  if (area === "superadmin") return normalized === "super_admin";
  return true;
}

function postLoginRedirectForRole(role, fallback = defaultDashboardRouteForRole(role)) {
  const redirect = String(state.postLoginRedirect || "").trim();
  if (!redirect || !redirect.startsWith("/") || redirect.startsWith("//")) return fallback;
  const path = redirect.split(/[?#]/)[0] || "/";
  const area = protectedAreaForPath(path);
  if (area && !roleCanAccessArea(role, area)) return fallback;
  return redirect;
}

async function completeAuthenticatedLogin(payload, options = {}) {
  payload.profile.role = normalizeRole(payload.profile.role);
  saveSession(payload, { remember: options.remember !== false });
  await applyProfileLanguagePreference(payload);
  state.mode = appModeForRole(payload.profile.role);
  const redirect = postLoginRedirectForRole(payload.profile.role, options.redirectFallback || defaultDashboardRouteForRole(payload.profile.role));
  updateAuthDiagnostics({
    requestStatus: "HTTP 200",
    sessionPresent: true,
    resolvedRole: payload.profile.role,
    selectedRedirectRoute: redirect,
    errorCode: ""
  });
  state.postLoginRedirect = "";
  history.pushState(null, "", redirect);
  await renderCurrentMode();
  showToast(t("logged_in_toast", "Logged in."));
  return payload;
}

function currentSession() {
  if (state.session && isSessionExpired(state.session)) {
    state.session = null;
    clearStoredSession();
  }
  return state.session;
}

function isSuperAdmin() {
  return normalizeRole(currentSession()?.profile?.role) === "super_admin";
}

function isGuestSession() {
  const session = currentSession();
  return Boolean(session) && normalizeRole(session.profile?.role) === "guest";
}

function isAuthError(error) {
  const status = Number(error?.status || error?.payload?.status || 0);
  const code = String(error?.payload?.code || error?.payload?.error_code || error?.code || "").toUpperCase();
  if (status === 401) return true;
  if (status === 403 && /AUTH|JWT|TOKEN|SESSION/.test(code)) return true;
  if (["AUTH_SESSION_EXPIRED", "JWT_EXPIRED", "TOKEN_EXPIRED", "INVALID_TOKEN", "INVALID_JWT"].includes(code)) return true;
  const message = String(error?.message || "").toLowerCase();
  return /\b(authentication required|invalid or expired session|session expired|token expired|jwt expired)\b/.test(message);
}

function persistCurrentSession() {
  if (!state.session) return;
  const serialized = JSON.stringify(state.session);
  if (isPrivilegedWebSession(state.session) || state.session.remember_me === false) {
    sessionStorage.setItem("smarttable.session", serialized);
    localStorage.removeItem("smarttable.session");
  } else {
    localStorage.setItem("smarttable.session", serialized);
    sessionStorage.removeItem("smarttable.session");
  }
}

function saveSession(session, options = {}) {
  const remember = isPrivilegedWebSession(session)
    ? false
    : options.remember === false ? false : session?.remember_me !== false;
  state.session = withSessionExpiry(session, remember);
  if (session) {
    state.session.remember_me = remember;
    persistCurrentSession();
  } else {
    clearStoredSession();
  }
  updateAuthDiagnostics({
    sessionPresent: Boolean(state.session),
    resolvedRole: normalizeRole(state.session?.profile?.role || "")
  });
  updateAdminDashboardNav(state.session);
  updateSessionButton();
}

async function applyProfileLanguagePreference(session) {
  const stored = localStorage.getItem("smarttable.lang");
  if (stored) {
    state.lang = normalizeLanguage(stored);
    await persistLanguagePreference();
    return;
  }
  const preferred = session?.profile?.preferred_language;
  if (preferred) {
    const profileLanguage = normalizeLanguage(preferred);
    if (profileLanguage !== state.lang) {
      state.lang = profileLanguage;
      localStorage.setItem("smarttable.lang", state.lang);
      await loadTranslations();
    }
    return;
  }
  if (session?.profile) await persistLanguagePreference();
}

async function persistLanguagePreference() {
  localStorage.setItem("smarttable.lang", state.lang);
  if (!state.session?.access_token) return;
  state.session.profile = { ...(state.session.profile || {}), preferred_language: state.lang };
  persistCurrentSession();
  try {
    await api("/auth/language", {
      method: "PATCH",
      body: JSON.stringify({ preferred_language: state.lang })
    });
  } catch {
    // Language preference should never block the current UI.
  }
}

async function setLanguage(lang, options = {}) {
  const nextLanguage = normalizeLanguage(lang);
  state.languageSelectorOpen = false;
  if (state.lang === nextLanguage) {
    localStorage.setItem("smarttable.lang", state.lang);
    updateLanguageSelector();
    return;
  }
  state.lang = nextLanguage;
  localStorage.setItem("smarttable.lang", state.lang);
  if (options.persist !== false) await persistLanguagePreference();
  await renderCurrentMode();
}

function languageShortLabel(lang = state.lang) {
  const normalized = normalizeLanguage(lang);
  return LANGUAGE_SHORT_LABELS[normalized] || LANGUAGE_SHORT_LABELS.en;
}

function languageOptionLabel(lang = state.lang) {
  const normalized = normalizeLanguage(lang);
  return supportedLanguages[normalized]?.label || languageShortLabel(normalized);
}

function languageOptionButtons() {
  return Array.from(document.querySelectorAll("[data-language-option]"));
}

function focusLanguageOption(lang = state.lang) {
  const option = document.querySelector(`[data-language-option="${safeCssValue(lang)}"]`) || languageOptionButtons()[0];
  option?.focus();
}

function moveLanguageOptionFocus(direction) {
  const options = languageOptionButtons();
  if (!options.length) return;
  const currentIndex = Math.max(0, options.indexOf(document.activeElement));
  const nextIndex = (currentIndex + direction + options.length) % options.length;
  options[nextIndex].focus();
}

function updateLanguageSelector() {
  const root = document.querySelector("[data-language-selector]");
  if (!root) return;
  const button = root.querySelector("#languageSelectorButton");
  const menu = root.querySelector("#languageSelectorMenu");
  const label = root.querySelector("[data-language-selector-label]");
  const current = root.querySelector("[data-language-selector-current]");
  const code = root.querySelector("[data-language-selector-code]");
  const selectorLabel = t("language_selector_label", "Language");
  const menuLabel = t("language_selector_menu_label", "Choose language");
  const currentLabel = languageShortLabel(state.lang);

  root.classList.toggle("open", state.languageSelectorOpen);
  root.setAttribute("aria-label", selectorLabel);
  if (label) label.textContent = selectorLabel;
  if (current) current.textContent = currentLabel;
  if (code) code.textContent = normalizeLanguage(state.lang).toUpperCase();
  if (button) {
    button.setAttribute("aria-expanded", state.languageSelectorOpen ? "true" : "false");
    button.setAttribute("aria-label", `${selectorLabel}: ${currentLabel}`);
  }
  if (!menu) return;
  menu.hidden = !state.languageSelectorOpen;
  menu.setAttribute("aria-label", menuLabel);
  menu.innerHTML = Object.keys(supportedLanguages).map((lang) => {
    const active = state.lang === lang;
    return `
      <button
        class="language-selector__option ${active ? "active" : ""}"
        id="language-option-${escapeAttr(lang)}"
        type="button"
        role="option"
        data-language-option="${escapeAttr(lang)}"
        aria-selected="${active ? "true" : "false"}"
      >
        <span class="language-selector__check" aria-hidden="true">${active ? "\u2713" : ""}</span>
        <span>${escapeHtml(languageOptionLabel(lang))}</span>
      </button>
    `;
  }).join("");
}

function cityOptionButtons() {
  return Array.from(document.querySelectorAll("[data-city-option]:not([disabled])"));
}

