async function uploadMedia(kind, targetName) {
  const input = document.querySelector(`[data-upload-kind="${CSS.escape(kind)}"][data-upload-target="${CSS.escape(targetName)}"]`);
  const target = document.querySelector(`[name="${CSS.escape(targetName)}"]`);
  const file = input?.files?.[0];
  if (!file || !target) {
    showToast(t("image_choose_first_toast", "Choose an image first."));
    return;
  }
  try {
    const signed = await api("/partner/storage/sign-upload", {
      method: "POST",
      body: JSON.stringify({
        kind,
        filename: file.name,
        content_type: file.type
      })
    });

    if (signed.upload_url) {
      const uploadResponse = await fetch(signed.upload_url, {
        method: "PUT",
        headers: { "content-type": file.type },
        body: file
      });
      if (!uploadResponse.ok) throw new Error(t("image_upload_failed_error", "Image upload failed."));
    }

    if (target.tagName === "TEXTAREA") {
      target.value = [target.value.trim(), signed.public_url].filter(Boolean).join("\n");
    } else {
      target.value = signed.public_url;
    }
    showToast(signed.mode === "demo" ? t("image_upload_demo_prepared_toast", "Demo upload prepared. Configure Supabase Storage for real uploads.") : t("image_uploaded_toast", "Image uploaded."));
  } catch (error) {
    showToast(error.message);
  }
}

function formObject(form) {
  const formData = new FormData(form);
  const data = {};
  for (const [key, value] of formData.entries()) {
    if (data[key] === undefined) data[key] = value;
    else if (Array.isArray(data[key])) data[key].push(value);
    else data[key] = [data[key], value];
  }
  return data;
}

function normalizeContentLanguage(value = "") {
  const raw = String(value || "").trim().toLowerCase();
  if (raw.startsWith("hu") || raw.includes("hungary") || raw.includes("magyar") || raw.includes("budapest")) return "hu";
  if (raw.startsWith("es") || raw.includes("spain") || raw.includes("espa") || raw.includes("madrid") || raw.includes("barcelona")) return "es";
  return "en";
}

function primaryContentLanguageForRestaurant(restaurant = {}) {
  const candidates = [
    restaurant.content_language,
    restaurant.default_locale,
    restaurant.market_default_locale,
    restaurant.primary_locale,
    restaurant.locale,
    restaurant.language,
    restaurant.country_code,
    restaurant.country,
    restaurant.market_code,
    restaurant.market,
    restaurant.city_name,
    restaurant.city
  ].filter(Boolean);
  for (const candidate of candidates) {
    const lang = normalizeContentLanguage(candidate);
    if (lang !== "en" || /^(en|us|usa|united states|nyc|new york)/i.test(String(candidate))) return lang;
  }
  return "en";
}

function contentLanguageName(language = "en") {
  const lang = normalizeContentLanguage(language);
  if (lang === "hu") return t("content_language_hungarian", "Hungarian");
  if (lang === "es") return t("content_language_spanish", "Spanish");
  return t("content_language_english", "English");
}

function localizedContentField(item = {}, base = "title", lang = state.lang) {
  const requested = normalizeLanguage(lang);
  const fields = requested === "hu"
    ? [`${base}_hu`, `${base}_en`, `${base}_es`, base]
    : requested === "es"
      ? [`${base}_es`, `${base}_en`, `${base}_hu`, base]
      : [`${base}_en`, `${base}_es`, `${base}_hu`, base];
  for (const field of fields) {
    const value = item?.[field];
    if (String(value || "").trim()) return value;
  }
  return "";
}

function primaryOfferContentFields(restaurant = {}) {
  const language = primaryContentLanguageForRestaurant(restaurant);
  const languageName = contentLanguageName(language);
  return `
    <div class="single-language-content-card">
      <input type="hidden" name="content_language" value="${escapeAttr(language)}">
      <p class="form-note">
        ${escapeHtml(contentTemplate("offer_content_language_note", "This market uses {{language}} as the source language for offer content. Enter it once; SmartTable keeps the guest interface translated with the selected site language.", { language: languageName }))}
      </p>
      ${textInput("title_primary", t("offer_primary_title_label", "Offer title"), "", "text", "required")}
      ${textArea("description_primary", t("offer_primary_description_label", "Offer description"))}
    </div>
  `;
}

function primaryRestaurantContentFields(restaurant = {}) {
  const language = primaryContentLanguageForRestaurant(restaurant);
  const languageName = contentLanguageName(language);
  const description = localizedContentField(restaurant, "description", language) || restaurant.description || "";
  return `
    <div class="single-language-content-card">
      <input type="hidden" name="profile_content_language" value="${escapeAttr(language)}">
      <p class="form-note">
        ${escapeHtml(contentTemplate("restaurant_content_language_note", "This market uses {{language}} as the source language for restaurant profile content. Enter it once; SmartTable keeps the guest interface translated with the selected site language.", { language: languageName }))}
      </p>
      ${textArea("description_primary", t("restaurant_primary_description_label", "Restaurant description"), description)}
    </div>
  `;
}

function offerPayloadFromForm(form, restaurant = state.partnerProfile || {}) {
  const data = formObject(form);
  const language = normalizeContentLanguage(data.content_language || primaryContentLanguageForRestaurant(restaurant));
  const title = String(data.title_primary || "").trim();
  const description = String(data.description_primary || "").trim();
  delete data.content_language;
  delete data.title_primary;
  delete data.description_primary;
  delete data.title_en;
  delete data.title_es;
  delete data.title_hu;
  delete data.description_en;
  delete data.description_es;
  delete data.description_hu;
  data[`title_${language}`] = title;
  data[`description_${language}`] = description;
  if (language !== "en") {
    data.title_en = data.title_en || title;
    data.description_en = data.description_en || description;
  }
  return data;
}

function profilePayloadFromForm(form, restaurant = state.partnerProfile || {}) {
  const data = formObject(form);
  const language = normalizeContentLanguage(data.profile_content_language || primaryContentLanguageForRestaurant(restaurant));
  const description = String(data.description_primary || "").trim();
  delete data.profile_content_language;
  delete data.description_primary;
  delete data.description_en;
  delete data.description_es;
  delete data.description_hu;
  data[`description_${language}`] = description;
  data.description = description;
  if (language !== "en") data.description_en = data.description_en || description;
  return data;
}

async function loadPublicContent() {
  const payload = await api(`/public/content?lang=${encodeURIComponent(state.lang)}`);
  state.apiMode = payload.mode || state.apiMode;
  state.content = payload.content || {};
  updateMeta();
  updateChromeText();
}

async function loadFeatureStatus() {
  const payload = await api("/system/feature-status").catch(() => ({ features: [] }));
  state.featureStatus = payload.features || [];
}

async function loadPublicOffers() {
  const payload = await api(`/public/offers?lang=${encodeURIComponent(state.lang)}`);
  state.apiMode = payload.mode || state.apiMode;
  state.offers = payload.offers || [];
  updateMeta();
}

async function loadPublicRestaurants() {
  const includeTestData = new URLSearchParams(window.location.search).get("include_test_data");
  const testDataQuery = boolValue(includeTestData) ? "&include_test_data=true" : "";
  const payload = await api(`/public/restaurants?lang=${encodeURIComponent(state.lang)}${testDataQuery}`).catch(() => ({ restaurants: [] }));
  state.apiMode = payload.mode || state.apiMode;
  state.publicRestaurants = payload.restaurants || [];
  updateMeta();
}

async function loadNewestRestaurants() {
  const payload = await api(`/public/restaurants/newest?lang=${encodeURIComponent(state.lang)}`);
  state.apiMode = payload.mode || state.apiMode;
  state.newestRestaurants = payload.restaurants || [];
}

async function loadPublicConfig() {
  const payload = await api("/public/config");
  state.config = payload || {};
  state.apiMode = payload.mode || state.apiMode;
  state.platformMode = normalizePlatformMode(payload?.platform_mode);
  state.aiDemoVisibility = normalizeBooleanSetting(payload?.ai_demo_visibility, false);
  state.showAiModeBadge = normalizeBooleanSetting(payload?.show_ai_mode_badge, true);
  state.featureFlags = normalizeFeatureFlagSettings(payload?.feature_flags || {});
  state.featureRegistry = { ...defaultFeatureRegistry, ...(payload?.feature_registry || {}) };
}

function rewardsBookingIdFromUrl() {
  const url = new URL(window.location.href);
  if (!url.pathname.includes("/guest/rewards/photo-upload") && !url.searchParams.has("bookingId")) return "";
  return url.searchParams.get("bookingId") || url.searchParams.get("booking_id") || "";
}

async function loadRewardBookingContext() {
  const bookingId = rewardsBookingIdFromUrl();
  if (!bookingId) {
    state.rewardBookingContext = null;
    return;
  }
  try {
    const payload = await api(`/public/rewards/context?bookingId=${encodeURIComponent(bookingId)}`);
    state.rewardBookingContext = payload.context || null;
  } catch (error) {
    state.rewardBookingContext = { error: error.message, bookingId };
  }
}

async function loadAiPreferences() {
  if (!canShowFeature("ai.preferenceSurvey", { allowDemo: true })) {
    state.aiPreferences = null;
    return;
  }
  const payload = await api(`/ai/preferences?profile_key=${encodeURIComponent(state.aiProfileKey)}`);
  state.aiPreferences = payload.preferences ? { ...payload.preferences, guest_email: payload.profile?.guest_email || "" } : null;
}

async function loadAiRecommendations() {
  if (!canShowFeature("ai.concierge", { allowDemo: true })) {
    state.aiRecommendations = [];
    return;
  }
  const payload = await api(`/ai/recommendations?profile_key=${encodeURIComponent(state.aiProfileKey)}&lang=${encodeURIComponent(state.lang)}`);
  state.aiRecommendations = payload.recommendations || [];
}

async function trackAiEvent(eventType, metadata = {}) {
  if (!isAIConciergeMode()) return;
  try {
    await api("/ai/events", {
      method: "POST",
      body: JSON.stringify({
        profile_key: state.aiProfileKey,
        event_type: eventType,
        restaurant_id: metadata.restaurant_id || metadata.restaurantId || null,
        offer_id: metadata.offer_id || metadata.offerId || null,
        reservation_id: metadata.reservation_id || null,
        metadata
      })
    });
  } catch {
    // Learning signals are useful, but should never block the guest flow.
  }
}

function safeSignupAnalyticsMetadata(metadata = {}) {
  const allowed = [
    "path",
    "route_kind",
    "market_code",
    "step_index",
    "step_key",
    "field_key",
    "selected_count",
    "selected",
    "language",
    "platform_mode",
    "ai_concierge_visible",
    "completion_state",
    "source",
    "reason",
    "restaurant_count",
    "completed_steps_count",
    "preference_question_count",
    "terms_version",
    "privacy_policy_version",
    "marketing_consent",
    "has_error",
    "error_category",
    "action",
    "status",
    "target",
    "tab",
    "feature_key",
    "remember_me",
    "auth_provider",
    "request_type",
    "restaurant_id",
    "entry_point",
    "reservation_status",
    "notification_type",
    "settings_count",
    "channel_count",
    "session_scope"
  ];
  return Object.fromEntries(allowed
    .filter((key) => metadata[key] !== undefined)
    .map((key) => [key, metadata[key]]));
}

function signupStepAnalyticsMeta(stepIndex = ensureSignupState().step, extra = {}) {
  const step = signupSteps[stepIndex] || signupSteps[0];
  return safeSignupAnalyticsMetadata({
    step_index: stepIndex,
    step_key: step.key,
    language: state.lang,
    platform_mode: currentPlatformMode(),
    ai_concierge_visible: canShowFeature("ai.concierge", { audience: "guest", allowDemo: true }),
    source: "guest_signup",
    ...extra
  });
}

function trackSignupEvent(eventType, metadata = {}, options = {}) {
  if (!signupAnalyticsEvents.has(eventType)) return;
  trackSafeAnalyticsEvent(eventType, metadata, options);
}

function trackGuestAccountEvent(eventType, metadata = {}, options = {}) {
  if (!guestAccountAnalyticsEvents.has(eventType)) return;
  trackSafeAnalyticsEvent(eventType, {
    language: state.lang,
    platform_mode: currentPlatformMode(),
    ai_concierge_visible: canShowFeature("ai.concierge", { audience: "guest", allowDemo: true }),
    source: "guest_account",
    ...metadata
  }, options);
}

const anonymousPublicAnalyticsEvents = new Set(["guest_website_view", "restaurant_booking_options_viewed"]);

function trackSafeAnalyticsEvent(eventType, metadata = {}, options = {}) {
  const payload = {
    event_type: eventType,
    metadata: safeSignupAnalyticsMetadata(metadata)
  };
  if (!anonymousPublicAnalyticsEvents.has(eventType)) payload.profile_key = state.aiProfileKey;
  const body = JSON.stringify(payload);
  try {
    if (options.keepalive && navigator.sendBeacon) {
      navigator.sendBeacon("/api/analytics/events", new Blob([body], { type: "application/json" }));
      return;
    }
    fetch("/api/analytics/events", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body,
      keepalive: Boolean(options.keepalive)
    }).catch(() => {});
  } catch {
    // Analytics must never block account creation or navigation.
  }
}

const guestWebsiteAnalyticsHosts = new Set(["smarttablenyc.com", "www.smarttablenyc.com"]);
const guestWebsiteAnalyticsRouteKinds = new Set(["home", "restaurants", "restaurant-detail", "offers", "food-feed", "info"]);
let lastTrackedGuestWebsitePath = "";

function guestWebsiteAnalyticsRoute(route = currentPublicGuestRoute()) {
  const hostname = String(window.location.hostname || "").toLowerCase();
  if (!guestWebsiteAnalyticsHosts.has(hostname)) return null;
  if (currentAiRoute() || !guestWebsiteAnalyticsRouteKinds.has(route?.kind)) return null;
  const path = window.location.pathname.replace(/\/+$/, "") || "/";
  return { path, routeKind: route.kind };
}

function resetGuestWebsiteAnalyticsForCurrentRoute() {
  if (!guestWebsiteAnalyticsRoute()) lastTrackedGuestWebsitePath = "";
}

function trackGuestWebsiteView(route = currentPublicGuestRoute()) {
  const analyticsRoute = guestWebsiteAnalyticsRoute(route);
  if (!analyticsRoute) {
    lastTrackedGuestWebsitePath = "";
    return;
  }
  if (lastTrackedGuestWebsitePath === analyticsRoute.path) return;
  lastTrackedGuestWebsitePath = analyticsRoute.path;
  trackSafeAnalyticsEvent("guest_website_view", {
    path: analyticsRoute.path,
    route_kind: analyticsRoute.routeKind,
    language: state.lang,
    market_code: state.config?.resolved_market_code || state.config?.default_market_code || "",
    source: "guest_website"
  });
}

function trackRestaurantBookingOptionsView(restaurantId, entryPoint) {
  const analyticsRoute = guestWebsiteAnalyticsRoute();
  if (!analyticsRoute || !restaurantId) return;
  trackSafeAnalyticsEvent("restaurant_booking_options_viewed", {
    restaurant_id: restaurantId,
    entry_point: entryPoint,
    path: analyticsRoute.path,
    route_kind: analyticsRoute.routeKind,
    language: state.lang,
    market_code: state.config?.resolved_market_code || state.config?.default_market_code || "",
    source: "guest_website"
  });
}

function maybeTrackSignupAbandoned(reason = "navigation", keepalive = false) {
  const signup = state.signup;
  if (!signup || signup.analyticsCompleted || signup.analyticsAbandoned) return;
  const hasProgress = signup.step > 0 || Object.values(signup.data || {}).some((value) => {
    if (Array.isArray(value)) return value.length > 0;
    if (typeof value === "boolean") return value;
    return String(value || "").trim().length > 0;
  });
  if (!hasProgress) return;
  signup.analyticsAbandoned = true;
  trackSignupEvent("signup_abandoned", signupStepAnalyticsMeta(signup.step, {
    reason,
    completion_state: "incomplete",
    completed_steps_count: signup.step
  }), { keepalive });
}

