function adminDataApi(label, path, fallback, options = {}) {
  return adminDataWithFallback(
    label,
    () => api(path, { ...options, timeoutMs: ADMIN_DATA_REQUEST_TIMEOUT_MS }),
    fallback
  );
}

async function loadAdminData(options = {}) {
  state.adminLoadWarnings = [];
  if (normalizeRole(currentSession()?.profile?.role) === "field_representative") {
    const [accessContext, stats, restaurants, partners] = await Promise.all([
      adminDataApi("access-context", "/admin/access-context", { access: { market_ids: [] }, markets: [] }),
      adminDataApi("stats", "/admin/stats", () => ({ stats: state.stats || {} })),
      adminDataWithFallback("restaurants", () => fetchAdminRestaurantList({ ...options, requestTimeoutMs: ADMIN_DATA_REQUEST_TIMEOUT_MS }), () => ({ restaurants: state.restaurants || [] })),
      adminDataApi("partners", "/admin/partners", () => ({ partners: state.partners || [] }))
    ]);
    state.adminAccessContext = accessContext;
    state.stats = stats.stats || {};
    state.restaurants = restaurants.restaurants || [];
    state.partners = partners.partners || [];
    state.adminOffers = [];
    state.reservations = [];
    state.notifications = [];
    state.unreadNotifications = 0;
    return;
  }
  state.adminAccessContext = null;
  const adminAiEnabled = canShowFeature("ai.adminAIControls", { allowDemo: true });
  const basicMode = isBasicMode();
  const analyticsFilters = {
    ...state.adminAnalyticsFilters,
    scope: isSuperAdmin() ? "superadmin" : "admin"
  };
  const [stats, restaurants, reservations, contentRows, partners, offers, reviews, foodFeed, photoSubmissions, notifications, systemMessages, trends, integrations, featureFlags, errors, billing, analytics, checklists, privacy, legal, reservationAlerts] = await Promise.all([
    adminDataApi("stats", "/admin/stats", () => ({ stats: state.stats || {} })),
    adminDataWithFallback("restaurants", () => fetchAdminRestaurantList({ ...options, requestTimeoutMs: ADMIN_DATA_REQUEST_TIMEOUT_MS }), () => ({ restaurants: state.restaurants || [] })),
    adminDataApi("reservations", `/admin/reservations${queryStringFromFilters(state.adminReservationFilters)}`, () => ({ reservations: state.reservations || [] })),
    adminDataApi("content", "/admin/content", () => ({ content: state.contentRows || [] })),
    adminDataApi("partners", "/admin/partners", () => ({ partners: state.partners || [] })),
    adminDataApi("offers", "/admin/offers", () => ({ offers: state.adminOffers || [] })),
    adminDataApi("reviews", `/admin/reviews${queryStringFromFilters(state.adminReviewFilters)}`, () => ({ reviews: state.adminReviews || [], pagination: state.adminReviewPagination })),
    adminDataApi("food-feed", "/admin/food-feed", { videos: [] }),
    basicMode ? Promise.resolve({ submissions: [] }) : adminDataApi("photo-submissions", "/admin/photo-reward-submissions", { submissions: [] }),
    adminDataApi("notifications", "/admin/notifications", { notifications: [], unread_count: 0 }),
    basicMode ? Promise.resolve({ campaigns: [], sms_provider: { configured: false } }) : adminDataApi("system-messages", "/admin/system-messages", { campaigns: [], sms_provider: { configured: false } }),
    adminAiEnabled ? adminDataApi("trends", "/ai/trends", { trends: null }) : Promise.resolve({ trends: null }),
    adminAiEnabled ? adminDataApi("integrations", "/admin/integrations", { providers: [], connections: [], sync_runs: [], errors: [] }) : Promise.resolve({ providers: [], connections: [], sync_runs: [], errors: [] }),
    adminAiEnabled ? adminDataApi("feature-flags", "/admin/feature-flags", { flags: [] }) : Promise.resolve({ flags: [] }),
    adminAiEnabled ? adminDataApi("errors", "/admin/errors", { app_errors: [], integration_errors: [], failed_emails: [], failed_ai_actions: [], admin_alerts: [] }) : Promise.resolve({ app_errors: [], integration_errors: [], failed_emails: [], failed_ai_actions: [], admin_alerts: [] }),
    adminDataApi("billing", "/admin/billing", { plans: [], subscriptions: [], invoices: [], payment_events: [], billing_events: [] }),
    adminDataApi("analytics", `/admin/analytics${queryStringFromFilters(analyticsFilters)}`, { analytics: null }),
    adminAiEnabled ? adminDataApi("checklists", "/system/checklists", { checklists: null }) : Promise.resolve({ checklists: null }),
    adminDataApi("privacy", "/privacy/requests", { requests: [] }),
    adminDataApi("legal", "/admin/legal-documents", { documents: [], counts: {} }),
    adminDataApi("reservation-alerts", "/admin/reservation-alerts", { preferences: [], devices: [], alerts: [], deliveries: [], restaurants_without_push_device: [], offline_devices_over_24h: [] })
  ]);
  state.stats = stats.stats;
  state.restaurants = restaurants.restaurants || [];
  state.reservations = reservations.reservations || [];
  state.contentRows = contentRows.content || [];
  state.partners = partners.partners || [];
  state.adminOffers = offers.offers || [];
  state.adminReviews = reviews.reviews || [];
  state.adminFoodFeedVideos = foodFeed.videos || [];
  state.adminReviewPagination = reviews.pagination || { page: 1, page_size: state.adminReviewFilters.page_size || 25, total: state.adminReviews.length, total_pages: 1 };
  state.adminPhotoSubmissions = photoSubmissions.submissions || [];
  state.notifications = notifications.notifications || [];
  state.unreadNotifications = notifications.unread_count || 0;
  state.adminSystemMessages = systemMessages || null;
  state.platformTrends = trends.trends || null;
  state.adminIntegrations = integrations || null;
  state.adminFeatureFlags = featureFlags.flags || [];
  state.adminErrors = errors || null;
  state.adminBilling = billing || null;
  state.adminAnalytics = analytics.analytics || null;
  state.systemChecklists = checklists.checklists || null;
  state.privacyRequests = privacy.requests || [];
  state.adminLegalDocuments = legal.documents || [];
  state.adminLegalCounts = legal.counts || {};
  state.adminReservationAlerts = reservationAlerts || null;
  if (isSuperAdmin()) {
    const fieldTeam = await adminDataApi("field-team", "/superadmin/field-representatives", { representatives: [], invitations: [], markets: [] });
    state.fieldRepresentatives = fieldTeam.representatives || [];
    state.fieldRepresentativeInvitations = fieldTeam.invitations || [];
    state.fieldRepresentativeMarkets = fieldTeam.markets || [];
  } else {
    state.fieldRepresentatives = [];
    state.fieldRepresentativeInvitations = [];
    state.fieldRepresentativeMarkets = [];
  }
}

async function fetchAdminRestaurantList(options = {}) {
  const freshRestaurantList = Boolean(options.forceFreshRestaurants);
  const restaurantListPath = freshRestaurantList
    ? `/admin/restaurants?fresh=${encodeURIComponent(Date.now())}`
    : "/admin/restaurants";
  const fetchOptions = freshRestaurantList
    ? { cache: "no-store", headers: { "cache-control": "no-store" }, timeoutMs: options.requestTimeoutMs }
    : { timeoutMs: options.requestTimeoutMs };
  return await api(restaurantListPath, fetchOptions);
}

async function replaceAdminRestaurantListFromServer(options = {}) {
  const restaurants = await fetchAdminRestaurantList(options);
  state.restaurants = restaurants.restaurants || [];
  return state.restaurants;
}

function contentEditor() {
  return `
    <article class="panel wide-panel" id="admin-content">
      <div class="section-title-row compact">
        <div><span class="section-kicker">Site content</span><h2>Public content editor</h2></div>
        <button class="primary-button" id="saveContent" type="button">Save content</button>
      </div>
      <div class="table-wrap">
        <table class="content-table">
          <thead><tr><th>Key</th><th>English</th><th>Espa\u00f1ol</th><th>Magyar</th><th>Type</th></tr></thead>
          <tbody>
            ${state.contentRows.map((row) => `
              <tr class="content-row" data-key="${escapeAttr(row.key)}" data-type="${escapeAttr(row.content_type)}" data-group="${escapeAttr(row.group_name)}">
                <td><strong>${escapeHtml(row.key)}</strong><br><span class="muted">${escapeHtml(row.group_name)}</span></td>
                <td><textarea data-field="value_en">${escapeHtml(row.value_en || "")}</textarea></td>
                <td><textarea data-field="value_es">${escapeHtml(row.value_es || "")}</textarea></td>
                <td><textarea data-field="value_hu">${escapeHtml(row.value_hu || "")}</textarea></td>
                <td>${escapeHtml(row.content_type || "text")}</td>
              </tr>
            `).join("")}
          </tbody>
        </table>
      </div>
    </article>
  `;
}

function contentEditorV2() {
  const query = state.contentSearch.toLowerCase().trim();
  const rows = state.contentRows.filter((row) => {
    const haystack = `${row.key} ${row.group_name} ${row.value_en} ${row.value_es} ${row.value_hu}`.toLowerCase();
    return !query || haystack.includes(query);
  });
  return `
    <article class="panel wide-panel" id="admin-content">
      <div class="section-title-row compact">
        <div><span class="section-kicker">Site content</span><h2>Public content editor</h2></div>
      </div>
      <input class="content-search" id="contentSearch" value="${escapeAttr(state.contentSearch)}" placeholder="Search content key, group, or page text">
      <div class="content-card-list">
        ${rows.map((row) => `
          <button class="content-card" data-edit-content="${escapeAttr(row.key)}" type="button">
            <span>
              <strong>${escapeHtml(row.key)}</strong>
              <small>${escapeHtml(row.group_name)} - ${escapeHtml(row.content_type || "text")}</small>
            </span>
            <span class="content-preview">${escapeHtml(row.value_en || row.value_es || row.value_hu || "")}</span>
          </button>
        `).join("") || '<div class="empty-state">No matching content keys.</div>'}
      </div>
    </article>
    ${contentEditModal()}
  `;
}

function contentEditModal() {
  const row = state.contentRows.find((item) => item.key === state.contentEditKey);
  if (!row) return "";
  return `
    <div class="modal-backdrop" role="presentation">
      <section class="modal-card" role="dialog" aria-modal="true">
        <div class="dialog-head">
          <div>
            <span class="section-kicker">${escapeHtml(row.group_name)}</span>
            <h2>${escapeHtml(row.key)}</h2>
          </div>
          <button class="icon-button" data-close-content-modal type="button" aria-label="${escapeAttr(t("modal_cancel_label", "Cancel"))}">X</button>
        </div>
        <form class="mini-form" id="contentEditForm" data-key="${escapeAttr(row.key)}" data-group="${escapeAttr(row.group_name)}" data-type="${escapeAttr(row.content_type)}">
          <label>English<textarea name="value_en">${escapeHtml(row.value_en || "")}</textarea></label>
          <label>Spanish<textarea name="value_es">${escapeHtml(row.value_es || "")}</textarea></label>
          <label>Hungarian<textarea name="value_hu">${escapeHtml(row.value_hu || "")}</textarea></label>
          <div class="button-row">
            <button class="primary-button" type="submit">Save</button>
            <button class="ghost-button" data-close-content-modal type="button">${escapeHtml(t("modal_cancel_label", "Cancel"))}</button>
          </div>
        </form>
      </section>
    </div>
  `;
}

